import clsx from 'clsx';
import React, { forwardRef } from 'react';
import { isElement } from 'react-is';

import { visualContainerCSS } from './Visual.sty.js';
import type { DataTestId } from '../../../core/types/data-props.js';
import type { StylingProps } from '../../../core/types/styling-props.js';
import type { WithChildren } from '../../../core/types/with-children.js';
import { visualSlotCss } from '../EmptyState.sty.js';

//#region Typings
// eslint-disable-next-line @typescript-eslint/no-empty-interface
export interface EmptyStateVisualProps
  extends WithChildren,
    StylingProps,
    DataTestId {}
//#endregion Typings

/**
 * Typeguard function that will check if a React.Node is a EmptyState.Visual
 * @internal
 */
export function _isEmptyStateVisual(
  child: React.ReactNode,
): child is React.ReactElement<EmptyStateVisualProps> {
  return isElement(child) && child.type === Visual;
}

/** Container for the Visual slot of the EmptyState component. */
export const Visual = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  EmptyStateVisualProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  } = props;

  return (
    <div
      ref={forwardedRef}
      className={clsx([visualContainerCSS, visualSlotCss, consumerClassName])}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {children}
    </div>
  );
});

(Visual as typeof Visual & { displayName: string }).displayName =
  'EmptyState.Visual';
